#include "resident/domains/growth/growth_model.hpp"
// 死亡只停止尚未提供的服务，不退已真实支付的原住宿费用、不让死者继续挣恢复点。
#include "growth_recovery_completion.hpp"
#include <algorithm>
namespace hanmo::resident {namespace {
std::size_t pos(const CommonStore& c,const StableId& id){const auto& ids=c.state().facts.order();return std::size_t(std::find(ids.begin(),ids.end(),id)-ids.begin());}
}
Outcome<GrowthRecoveryCompletion> read_growth_recovery_completion(const CommonStore& c,const GrowthState& growth,const GrowthRecoveryState& state,const StableId& id){auto shape=validate_growth_recovery_shape(state);if(!shape.ok)return {false,{},shape.error};const auto* closed=state.closures.find(id);const auto* header=c.state().facts.find(id);if(!closed||!header||header->kind!="personal_recovery_closed"||header->domain!="personal_injury_recovery")return {false,{},common_failure("GrowthRecoveryCompletionSourceRequired",id).error};const auto* service=state.services.find(closed->action_id);const auto* original=growth.life_activities.find(closed->action_id);if(!service||!original||pos(c,closed->action_id)>=pos(c,id)||original->view.completed_tick!=closed->tick||original->view.actor_id!=service->actor_id||original->view.provider_actor_id!=service->provider_actor_id||original->view.phase!=(closed->reason=="completed"?LifeActivityPhase::completed:LifeActivityPhase::cancelled))return {false,{},common_failure("GrowthRecoveryCompletionSourceMismatch",id).error};GrowthRecoveryCompletion out;out.source_fact_id=id;out.action_id=closed->action_id;out.actor_id=service->actor_id;out.provider_actor_id=service->provider_actor_id;out.reason=closed->reason;out.tick=closed->tick;out.provided_half_days=closed->provided_half_days;out.success=closed->reason=="completed";out.code=out.success?"":closed->reason=="cancelled"?"RecoveryCancelled":closed->reason=="patient_dead"?"RecoveryPatientDied":"RecoveryProviderDied";return {true,std::move(out),{}};}
Outcome<std::vector<GrowthRecoveryCompletion>> terminate_dead_growth_recovery_services_in_candidate(CommonStore& c,GrowthState& growth,const GrowthRecoveryCatalog& catalog,GrowthRecoveryState& state,const GrowthRecoveryHistoryAccess& access,const std::function<Status(const StableId&)>& release,const DynamicStepInput* phase){std::vector<GrowthRecoveryCompletion> out;if(!access.death_source||!release)return {false,{},common_failure("GrowthRecoveryTerminationServicesRequired").error};const auto services=state.services.order();for(const auto& action:services){const auto* service=state.services.find(action);bool already=false;for(const auto& row:state.closures.rows())if(row.second.action_id==action){already=true;break;}if(already)continue;std::optional<FamilyDeathOrigin> first;StableId reason;for(const auto* actor:{&service->actor_id,&service->provider_actor_id}){const auto* p=c.actor(*actor);if(!p)return {false,{},common_failure("UnknownRecoveryActor",*actor).error};if(p->alive)continue;auto source=access.death_source(*actor,phase);if(!source.ok)return {false,{},source.error};if(!source.value)return {false,{},common_failure("GrowthRecoveryDeathSourceUnknown",*actor).error};if(!first||pos(c,source.value->casualty_fact_id)<pos(c,first->casualty_fact_id)){first=source.value;reason=*actor==service->actor_id?"patient_dead":"provider_dead";}}
if(!first)continue;const auto expected=phase?phase->to_tick:c.tick();if(first->tick!=expected)return {false,{},common_failure("GrowthRecoveryDeathTerminationLate",action).error};auto stopped=stop_growth_recovery_service_in_candidate(c,growth,catalog,state,access,action,reason,first->casualty_fact_id,phase);if(!stopped.ok)return {false,{},stopped.error};StableId closed_id;for(const auto& row:state.closures.rows())if(row.second.action_id==action)closed_id=row.first;auto completion=read_growth_recovery_completion(c,growth,state,closed_id);if(!completion.ok)return {false,{},completion.error};auto released=release(action);if(!released.ok)return {false,{},released.error};out.push_back(std::move(completion.value));}return {true,std::move(out),{}};}
}
